  \coordinate (vB) at (3.0,1.2);
  \coordinate (vC) at (1.6,0.0);
  \coordinate (vD) at (0.2,1.2);
  \draw[ink,fill=brand!8] (vA) -- (vB) -- (vC) -- (vD) -- cycle;
  \draw[brand,line width=1.0pt] (vA) -- (vC);
  \node[above] at (vA) {$A$};
  \node[right] at (vB) {$B$};
  \node[below] at (vC) {$C$};
  \node[left] at (vD) {$D$};
  \node[brand,font=\scriptsize] at (1.4,0.45) {$35^\circ$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Ví dụ 1}
\end{minipage}

\par\nopagebreak
\begin{minipage}[t]{0.62\linewidth}\vspace{0pt}
\textbf{Ví dụ 2.} Cho tam giác $ABC$ có tia phân giác $AD$. Qua $D$ kẻ đường thẳng song song với $AB$ cắt $AC$ tại $E$, kẻ đường thẳng song song với $AC$ cắt $AB$ tại $F$. Chứng minh tứ giác $AEDF$ là hình thoi.[[br]]{\sffamily\bfseries\color{brand}Lời giải}[[br]]\hspace*{1.4em}Xét tứ giác $AEDF$, ta có $DE \parallel AF$ (do $DE \parallel AB$) và $DF \parallel AE$ (do $DF \parallel AC$).[[br]]\hspace*{1.4em}Do đó tứ giác $AEDF$ là hình bình hành.[[br]]\hspace*{1.4em}Mặt khác, đường chéo $AD$ là tia phân giác của góc $\widehat{FAE}$ (theo giả thiết).[[br]]\hspace*{1.4em}Hình bình hành $AEDF$ có một đường chéo là tia phân giác của một góc nên là hình thoi.[[br]]\hspace*{1.4em}Vậy $AEDF$ là hình thoi.
\end{minipage}\hfill
