  \node[below] at (vD) {$D$};
  \node[above right] at (vE) {$E$};
  \node[above left] at (vF) {$F$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Ví dụ 2}
\end{minipage}

